contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        require(recipient != address(0));
        require(recipient != address(c));

        uint256 balBefore = address(c).balance;

        bool reverted;
        c.withdrawReward(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = address(c).balance;

        bool secondReverted;
        c.withdrawReward(recipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // The nonReentrant lock must always be released, so the second call can only
        // revert because the first call transferred Ether, never because _locked stayed true.
        assert(!(!secondReverted && reverted) || (balBefore <= balAfter));
    }

    receive() external payable {}
}

